bool trySend(std::atomic<int>& credits) {
    int c = credits.load(std::memory_order_relaxed);
    while (c > 0) {
        // on failure c is reloaded with the current value
        if (credits.compare_exchange_weak(c, c - 1,
                std::memory_order_acquire,
                std::memory_order_relaxed))
            return true;
    }
    return false;
}
// release side: credits.fetch_add(1, std::memory_order_release)
// when the receiver returns a credit

